    public static function key(string $source):string{return 'donation_form_'.substr(hash('sha256',$source),0,16);}
    public static function messages(string $locale):array{$en=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$source=>$english)$out[self::key($source)]=$en?$english:$source;return $out;}
    public static function text(string $source,array $messages):string
    {
        if(isset(self::ENGLISH[$source]))return $messages[self::key($source)]??$source;
        $fields=['issuer'=>'Vollständiger Vereinsname und Anschrift','donor'=>'Name und Anschrift des Zuwenders','purpose'=>'Begünstigter Zweck / Zwecke','tax_office'=>'Finanzamt','tax_number'=>'Steuernummer','assessment_period'=>'Veranlagungszeitraum','goods_description'=>'Genaue Bezeichnung der Sachzuwendung, Alter und Zustand','signature_place_date'=>'Ort und Datum für die spätere Unterschrift','amount'=>'Betrag in Euro','donated_on'=>'Datum der Zuwendung','notice_date'=>'Datum des Bescheids','notice_type'=>'Bescheidart','waiver'=>'Verzicht auf Erstattung von Aufwendungen','goods_origin'=>'Herkunft','search'=>'Suchtext'];
        if(preg_match('/^(?:Feld|Auswahl) ([a-z_]+) (prüfen|ausfüllen bzw\. kürzen)\.$/uD',$source,$match)&&isset($fields[$match[1]])){
            $template=$match[2]==='prüfen'?'Feld „{field}“ prüfen.':'Feld „{field}“ ausfüllen bzw. kürzen.';
            return str_replace('{field}',self::text($fields[$match[1]],$messages),self::text($template,$messages));
        }
        if(preg_match('/^Für die Ausstellung fehlen: (.+)\.$/uD',$source,$match)){
            $missing=explode(', ',$match[1]);foreach($missing as$item)if(!isset(self::ENGLISH[$item]))return $source;
            return str_replace('{fields}',implode(', ',array_map(static fn($item)=>self::text($item,$messages),$missing)),self::text('Für die Ausstellung fehlen: {fields}.',$messages));
        }
        return ManagerMessages::text($source,$messages);
    }
